# Paste lines of name,amount,date,note: per line, in order, for the named person, the claim the
# claim form would add (or the matching DRAFT updated to the line's amount), then opened as the open
# button would. One refused line refuses the paste and writes nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidatePasteClaims
  next: add
# Runs in a transaction of its own (not governed), so a refused line rolls back the lines before it;
# audits each line's changes, then the figures they moved, only once the whole paste went through.
add:
  class: net.officefloor.hq.app.claim.AddPastedClaims
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithPasteClaims
